func (siw *ServerInterfaceWrapper) CreateTokens(c *gin.Context) {

	for _, middleware := range siw.HandlerMiddlewares {
		middleware(c)
		if c.IsAborted() {
			return
		}
	}

	siw.Handler.CreateTokens(c)
}

// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.GET(options.BaseURL+"/v2/authorizations", wrapper.StartAuthorization)
	router.GET(options.BaseURL+"/v2/authorizations/callback", wrapper.FinishAuthorization)
	router.POST(options.BaseURL+"/v2/tokens", wrapper.CreateTokens)
	router.GET(options.BaseURL+"/v2/ops", wrapper.ListOps)
	router.POST(options.BaseURL+"/v2/ops", wrapper.PushOps)
	router.GET(options.BaseURL+"/v2/key", wrapper.GetKey)
	router.PUT(options.BaseURL+"/v2/key", wrapper.PutKey)
	router.GET(options.BaseURL+"/v2/snapshot", wrapper.GetSnapshot)
	router.PUT(options.BaseURL+"/v2/snapshot", wrapper.PutSnapshot)
	router.GET(options.BaseURL+"/v2/pairings", wrapper.ListPairings)
	router.POST(options.BaseURL+"/v2/pairings", wrapper.CreatePairing)
	router.GET(options.BaseURL+"/v2/pairings/:pairing_id", wrapper.GetPairing)
	router.PUT(options.BaseURL+"/v2/pairings/:pairing_id", wrapper.PutPairingMessage)
	router.GET(options.BaseURL+"/v2/devices", wrapper.ListDevices)
	router.DELETE(options.BaseURL+"/v2/devices/:device_id", wrapper.DeleteDevice)
	router.POST(options.BaseURL+"/v2/shares", wrapper.CreateShare)
	router.DELETE(options.BaseURL+"/v2/shares/:share_id", wrapper.DeleteShare)
	router.GET(options.BaseURL+"/v2/shares/:share_id", wrapper.GetShare)
	router.GET(options.BaseURL+"/v2/shares/:share_id/view", wrapper.ViewShare)
}

