// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// StartAuthorization Send the browser to the OIDC issuer.
	// (GET /v2/authorizations)
	StartAuthorization(ctx context.Context, request StartAuthorizationRequestObject) (StartAuthorizationResponseObject, error)
	// FinishAuthorization Take the issuer's answer and send the browser back to the client.
	// (GET /v2/authorizations/callback)
	FinishAuthorization(ctx context.Context, request FinishAuthorizationRequestObject) (FinishAuthorizationResponseObject, error)
	// ListDevices List the caller's devices, oldest first.
	// (GET /v2/devices)
	ListDevices(ctx context.Context, request ListDevicesRequestObject) (ListDevicesResponseObject, error)
	// DeleteDevice Revoke one of the caller's devices and its tokens.
	// (DELETE /v2/devices/{device_id})
	DeleteDevice(ctx context.Context, request DeleteDeviceRequestObject) (DeleteDeviceResponseObject, error)
	// GetKey Read the caller's wrapped data key.
	// (GET /v2/key)
	GetKey(ctx context.Context, request GetKeyRequestObject) (GetKeyResponseObject, error)
	// PutKey Store the caller's wrapped data key, once.
	// (PUT /v2/key)
	PutKey(ctx context.Context, request PutKeyRequestObject) (PutKeyResponseObject, error)
	// ListOps Read the caller's log after a seq, oldest first.
	// (GET /v2/ops)
	ListOps(ctx context.Context, request ListOpsRequestObject) (ListOpsResponseObject, error)
	// PushOps Append ops to the caller's log.
	// (POST /v2/ops)
	PushOps(ctx context.Context, request PushOpsRequestObject) (PushOpsResponseObject, error)
	// ListPairings List the caller's pairings that have not expired, oldest first.
	// (GET /v2/pairings)
	ListPairings(ctx context.Context, request ListPairingsRequestObject) (ListPairingsResponseObject, error)
	// CreatePairing Open a pairing for the calling device, the new one.
	// (POST /v2/pairings)
	CreatePairing(ctx context.Context, request CreatePairingRequestObject) (CreatePairingResponseObject, error)
	// GetPairing Read one of the caller's pairings.
	// (GET /v2/pairings/{pairing_id})
	GetPairing(ctx context.Context, request GetPairingRequestObject) (GetPairingResponseObject, error)
	// PutPairingMessage Store one message of the exchange.
	// (PUT /v2/pairings/{pairing_id})
	PutPairingMessage(ctx context.Context, request PutPairingMessageRequestObject) (PutPairingMessageResponseObject, error)
	// CreateShare Store a sealed group for its share URL.
	// (POST /v2/shares)
	CreateShare(ctx context.Context, request CreateShareRequestObject) (CreateShareResponseObject, error)
	// DeleteShare Stop sharing one of the caller's shares.
	// (DELETE /v2/shares/{share_id})
	DeleteShare(ctx context.Context, request DeleteShareRequestObject) (DeleteShareResponseObject, error)
	// GetShare Read a share. The share URL is the only credential.
	// (GET /v2/shares/{share_id})
	GetShare(ctx context.Context, request GetShareRequestObject) (GetShareResponseObject, error)
	// ViewShare The web page that opens a share in a browser.
	// (GET /v2/shares/{share_id}/view)
	ViewShare(ctx context.Context, request ViewShareRequestObject) (ViewShareResponseObject, error)
	// GetSnapshot Read the caller's snapshot.
	// (GET /v2/snapshot)
	GetSnapshot(ctx context.Context, request GetSnapshotRequestObject) (GetSnapshotResponseObject, error)
	// PutSnapshot Replace the caller's snapshot with one of a later seq.
	// (PUT /v2/snapshot)
	PutSnapshot(ctx context.Context, request PutSnapshotRequestObject) (PutSnapshotResponseObject, error)
	// CreateTokens Trade a login code or a refresh token for a token pair.
	// (POST /v2/tokens)
	CreateTokens(ctx context.Context, request CreateTokensRequestObject) (CreateTokensResponseObject, error)
}

type StrictHandlerFunc func(ctx *gin.Context, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictGinServerOptions struct {
	// RequestErrorHandlerFunc is called when a request cannot be parsed or
	// decoded. It is invoked for JSON bind failures, form parse/bind errors,
	// multipart reader errors, media type parse errors, missing multipart
	// boundaries, and request body read errors. The default returns 400.
	RequestErrorHandlerFunc func(ctx *gin.Context, err error)
	// HandlerErrorFunc is called when the application handler (or any
	// middleware wrapping it) returns a non-nil error. The default returns 500.
	HandlerErrorFunc func(ctx *gin.Context, err error)
	// ResponseErrorHandlerFunc is called when the response object fails to
	// serialize (Visit*Response returns an error) or when the handler returns
	// an unexpected response type. The default returns 500.
	ResponseErrorHandlerFunc func(ctx *gin.Context, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictGinServerOptions{
		RequestErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		},
		HandlerErrorFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
		ResponseErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictGinServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		}
	}
	if options.HandlerErrorFunc == nil {
		options.HandlerErrorFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

